32	import type { Result } from "@/pages/Index";
33	import type { HiringStage } from "@/hooks/useStageTracker";
34	
35	import CandidateSummaryCard from "@/components/candidate/CandidateSummaryCard";
36	import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
37	import ExperiencePanel from "@/components/candidate/ExperiencePanel";
38	import EducationPanel from "@/components/candidate/EducationPanel";
