58	
59	// ── Local sub-components ────────────────────────────────────────────────────
60	
61	function ScoreRingMini({ score }: { score: number }) {
62	  const size = 56;
63	  const sw = 5;
64	  const r = (size - sw) / 2;
65	  const c = 2 * Math.PI * r;
66	  const v = Math.min(Math.max(score, 0), 100);
67	  const dash = (v / 100) * c;
68	  const color = v >= 70 ? "#22c55e" : v >= 40 ? "#f59e0b" : "#ef4444";
69	  return (
70	    <div
71	      className="relative inline-flex items-center justify-center shrink-0"
72	      style={{ width: size, height: size }}
73	    >
74	      <svg width={size} height={size} className="-rotate-90">
75	        <circle
76	          cx={size / 2}
77	          cy={size / 2}
78	          r={r}
79	          fill="none"
80	          stroke="currentColor"
81	          strokeWidth={sw}
82	          className="text-muted/30"
83	        />
84	        <circle
85	          cx={size / 2}
86	          cy={size / 2}
87	          r={r}
88	          fill="none"
89	          stroke={color}
90	          strokeWidth={sw}
91	          strokeDasharray={`${dash} ${c - dash}`}
92	          strokeLinecap="round"
93	        />
94	      </svg>
95	      <span
96	        className="absolute text-sm font-bold tabular-nums"
97	        style={{ color }}
98	      >
99	        {Math.round(v)}
100	      </span>
101	    </div>
102	  );
103	}
104	
105	function MustHaveSkillsGrid({
106	  matched = [],
107	  missing = [],
108	}: {
109	  matched?: string[];
110	  missing?: string[];
111	}) {
112	  if (!matched.length && !missing.length) return null;
113	  return (
114	    <div>
115	      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
116	        Must-Have Skills
117	      </p>
118	      <div className="flex flex-wrap gap-2">
119	        {matched.map((s) => (
120	          <span
121	            key={s}
122	            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800"
123	          >
124	            <CheckCircle2 className="h-3 w-3" />
125	            {s}
126	          </span>
127	        ))}
128	        {missing.map((s) => (
129	          <span
130	            key={s}
131	            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-50 text-red-700 border border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-800"
132	          >
133	            <XCircle className="h-3 w-3" />
134	            {s}
135	          </span>
136	        ))}
137	      </div>
138	    </div>
139	  );
140	}
141	
142	// ── Props & helpers ──────────────────────────────────────────────────────────
143	
144	interface CandidateDetailSheetProps {
145	  result: Result | null;
146	  isOpen: boolean;
147	  onClose: () => void;
148	  jobId?: string | null;
149	  jobTitle?: string | null;
150	  teamId?: string | null;
151	  formatCandidateName: (filename: string) => string;
152	  onDownload: (filePath: string, filename: string) => void;
153	  onDismiss: (resumeId: string) => void;
154	  currentStage?: HiringStage | null;
155	  stageUpdatedAt?: string | null;
156	  onStageChange?: (resumeId: string, stage: HiringStage) => void;
157	  tags?: CandidateTag[];
158	  teamMembers?: TeamMember[];
159	  onAddTag?: (params: { resumeId: string; tag: string; color?: string }) => void;
160	  onRemoveTag?: (tagId: string) => void;
161	  onAssigned?: (resumeId: string, userId: string | null) => void;
162	  blindMode?: boolean;
163	}
164	
165	const getStrengthLabel = (
166	  score: number
167	): { label: string; variant: "success" | "warning" | "destructive" } => {
168	  if (score >= 70) return { label: "Strong", variant: "success" };
169	  if (score >= 40) return { label: "Good", variant: "warning" };
170	  return { label: "Weak", variant: "destructive" };
171	};
172	
173	// ── Main component ───────────────────────────────────────────────────────────
174	
175	const CandidateDetailSheet = ({
176	  result: r,
177	  isOpen,
178	  onClose,
179	  jobId,
180	  jobTitle,
181	  teamId,
182	  formatCandidateName,
183	  onDownload,
184	  onDismiss,
185	  currentStage,
186	  stageUpdatedAt,
187	  onStageChange,
188	  tags = [],
189	  teamMembers = [],
190	  onAddTag,
191	  onRemoveTag,
192	  onAssigned,
193	  blindMode = false,
194	}: CandidateDetailSheetProps) => {
195	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
196	  const [scheduleOpen, setScheduleOpen] = useState(false);
197	  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
198	  const [whatsappOpen, setWhatsappOpen] = useState(false);
199	  const [activeTab, setActiveTab] = useState("overview");
200	
201	  // Reset tab to overview each time the sheet opens
202	  useEffect(() => {
203	    if (isOpen) setActiveTab("overview");
204	  }, [isOpen]);
205	
206	  if (!r) return null;
207	
208	  const strength = getStrengthLabel(r.overall_score);
209	  const linkedinUrl = extractLinkedInUrl(r);
210	  const candidateName = r.candidate_name || formatCandidateName(r.filename);
211	  const initials = candidateName
212	    .split(" ")
213	    .slice(0, 2)
214	    .map((n: string) => n[0])
215	    .join("")
216	    .toUpperCase();
217	
218	  return (
219	    <>
220	      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
221	        <SheetContent
222	          side="right"
223	          className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden"
224	        >
225	          {/* ── Header ──────────────────────────────────────────────────── */}
226	          <div className="bg-card px-6 pt-5 pb-4 shrink-0 border-b border-border relative">
227	            {/* Close button */}
228	            <button
229	              onClick={onClose}
230	              className="absolute top-4 right-4 rounded-sm opacity-60 hover:opacity-100 transition-opacity"
231	            >
232	              <X className="h-4 w-4" />
233	            </button>
234	
235	            {/* Identity row */}
236	            <div className="flex items-start gap-3 pr-6">
237	              {/* Avatar */}
238	              <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
239	                <span className="text-sm font-semibold text-primary">{initials}</span>
240	              </div>
241	
242	              {/* Name + meta */}
243	              <div className="flex-1 min-w-0">
244	                <h2 className="text-lg font-semibold text-foreground truncate">
245	                  {blindMode ? "Candidate" : candidateName}
246	                </h2>
247	                <div className="flex items-center gap-3 mt-0.5 flex-wrap">
248	                  {r.candidate_location && (
249	                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
250	                      <MapPin className="h-3 w-3" />
251	                      {r.candidate_location}
252	                    </span>
253	                  )}
254	                  {r.candidate_email && (
255	                    <span className="text-xs text-muted-foreground truncate">
256	                      {r.candidate_email}
257	                    </span>
258	                  )}
259	                </div>
260	              </div>
261	
262	              {/* Score ring */}
263	              <ScoreRingMini score={r.overall_score ?? 0} />
264	            </div>
265	
266	            {/* Badge + confidence row */}
267	            <div className="flex items-center gap-2 mt-3 flex-wrap">
268	              <Badge variant={strength.variant}>{strength.label}</Badge>
269	              {r.scoring_version === "heuristic" && (
270	                <Badge variant="secondary">Quick</Badge>
